<?php
 namespace Pterodactyl\Services\Dezerx; use Pterodactyl\Models\Node; use Pterodactyl\Models\Permission; class Editor { public static function payload(): array { return [ 'schema' => Theme::editorSchema(), 'theme' => Theme::config(), 'appearance' => Appearance::payload() + ['tokens' => Appearance::tokens()], 'tokenGroups' => Appearance::TOKEN_GROUPS, 'fontCatalogue' => Appearance::fontCatalogue(), 'fontSlots' => Appearance::FONT_SLOTS, 'eggs' => Eggs::all(), 'nodes' => Node::query()->orderBy('name')->get(['id', 'name'])->map(fn (Node $node) => ['id' => (int) $node->id, 'name' => (string) $node->name])->all(), 'permissions' => Permission::permissions(), 'artKeywords' => Theme::ART_KEYWORDS, ]; } } 